```zig
const std = @import("std");
const http = std.http;
const net = std.net;
const mem = std.mem;
const json = std.json;
const CerebrasClient = @import("cerebras_client.zig").CerebrasClient;
const Router = @import("router.zig").Router;
const DragonflyClient = @import("dragonfly_client.zig").DragonflyClient;
const ModalClient = @import("modal_client.zig").ModalClient;
const KdbLogger = @import("kdb_logger.zig").KdbLogger;

const Config = struct {
    cerebras_api_key: []const u8,
    dragonfly_url: []const u8,
    dragonfly_password: []const u8,
    modal_api_url: []const u8,
    modal_api_key: []const u8,
    kdb_host: []const u8,
    kdb_port: u16,
    listen_addr: []const u8,
    listen_port: u16,
    num_threads: u32,
};

const Server = struct {
    allocator: mem.Allocator,
    config: Config,
    cerebras: *CerebrasClient,
    dragonfly: *DragonflyClient,
    modal: *ModalClient,
    kdb: *KdbLogger,
    router: *Router,
    server: http.Server,
    thread_pool: std.Thread.Pool,
    shutdown: std.atomic.Atomic(bool),

    fn init(allocator: mem.Allocator, config: Config) !*Server {
        const self = try allocator.create(Server);
        self.allocator = allocator;
        self.config = config;
        self.shutdown = std.atomic.Atomic(bool).init(false);

        self.dragonfly = try DragonflyClient.init(allocator, config.dragonfly_url, config.dragonfly_password);
        try self.dragonfly.connect();

        self.cerebras = try CerebrasClient.init(allocator, config.cerebras_api_key);

        self.modal = try ModalClient.init(allocator, config.modal_api_url, config.modal_api_key);

        self.kdb = try KdbLogger.init(allocator, config.kdb_host, config.kdb_port);
        try self.kdb.connect();

        self.router = try Router.init(allocator, self.cerebras, self.dragonfly, self.modal, self.kdb);

        try self.thread_pool.init(.{ .allocator = allocator, .n_jobs = config.num_threads });

        return self;
    }

    fn deinit(self: *Server) void {
        self.thread_pool.deinit();
        self.router.deinit();
        self.kdb.deinit();
        self.modal.deinit();
        self.cerebras.deinit();
        self.dragonfly.deinit();
        self.allocator.destroy(self);
    }

    fn start(self: *Server) !void {
        const addr = try net.Address.parseIp(self.config.listen_addr, self.config.listen_port);
        var listener = net.StreamServer.init(.{ .reuse_address = true });
        defer listener.deinit();
        try listener.listen(addr);

        std.log.info("Gateway listening on {s}:{d}", .{ self.config.listen_addr, self.config.listen_port });

        while (!self.shutdown.load(.Acquire)) {
            const connection = listener.accept() catch |err| {
                std.log.err("Accept failed: {}", .{err});
                continue;
            };

            try self.thread_pool.spawn(handleConnection, .{ self, connection });
        }
    }

    fn handleConnection(self: *Server, connection: net.StreamServer.Connection) void {
        defer connection.stream.close();

        var arena = std.heap.ArenaAllocator.init(self.allocator);
        defer arena.deinit();
        const arena_alloc = arena.allocator();

        var server = http.Server.init(connection, .{});
        var request = server.receiveHead() catch |err| {
            std.log.err("Failed to receive request: {}", .{err});
            return;
        };

        const start_time = std.time.nanoTimestamp();

        if (mem.eql(u8, request.head.target, "/search")) {
            self.handleSearch(arena_alloc, &request, start_time) catch |err| {
                std.log.err("Search failed: {}", .{err});
                self.sendError(&request, 500, "Internal server error") catch {};
            };
        } else if (mem.eql(u8, request.head.target, "/health")) {
            self.handleHealth(arena_alloc, &request) catch |err| {
                std.log.err("Health check failed: {}", .{err});
            };
        } else if (mem.eql(u8, request.head.target, "/stats")) {
            self.handleStats(arena_alloc, &request) catch |err| {
                std.log.err("Stats failed: {}", .{err});
            };
        } else {
            self.sendError(&request, 404, "Not found") catch {};
        }
    }

    fn handleSearch(self: *Server, allocator: mem.Allocator, request: *http.Server.Request, start_time: i64) !void {
        var body_buffer = std.ArrayList(u8).init(allocator);
        defer body_buffer.deinit();

        const reader = request.reader();
        try reader.readAllArrayList(&body_buffer, 1024 * 1024);

        const parsed = try json.parseFromSlice(json.Value, allocator, body_buffer.items, .{});
        defer parsed.deinit();

        const query = parsed.value.object.get("query").?.string;
        const deep_research = if (parsed.value.object.get("deep_research")) |dr| dr.bool else false;

        const result = try self.router.handleQuery(allocator, query, deep_research);
        defer allocator.free(result);

        const end_time = std.time.nanoTimestamp();
        const latency_ms = @as(f64, @floatFromInt(end_time - start_time)) / 1_000_000.0;

        try self.kdb.logQuery(start_time, result.model, latency_ms, result.tokens, result.cache_hit);

        try request.respond(result.response, .{
            .status = .ok,
            .extra_headers = &.{
                .{ .name = "Content-Type", .value = "application/json" },
            },
        });
    }

    fn handleHealth(self: *Server, allocator: mem.Allocator, request: *http.Server.Request) !void {
        _ = allocator;
        const dragonfly_ok = self.dragonfly.ping() catch false;
        const kdb_ok = self.kdb.isConnected();

        const response = if (dragonfly_ok and kdb_ok)
            "{\"status\":\"ok\",\"dragonfly\":true,\"kdb\":true}"
        else
            "{\"status\":\"degraded\",\"dragonfly\":" ++ (if (dragonfly_ok) "true" else "false") ++ ",\"kdb\":" ++ (if (kdb_ok) "true" else "false") ++ "}";

        try request.respond(response, .{
            .status = if (dragonfly_ok and kdb_ok) .ok else .service_unavailable,
            .extra_headers = &.{
                .{ .name = "Content-Type", .value = "application/json" },
            },
        });
    }

    fn handleStats(self: *Server, allocator: mem.Allocator, request: *http.Server.Request) !void {
        const stats = try self.router.getStats(allocator);
        defer allocator.free(stats);

        try request.respond(stats, .{
            .status = .ok,
            .extra_headers = &.{
                .{ .name = "Content-Type", .value = "application/json" },
            },
        });
    }

    fn sendError(self: *Server, request: *http.Server.Request, status_code: u16, message: []const u8) !void {
        _ = self;
        const status: http.Status = @enumFromInt(status_code);
        const body = try std.fmt.allocPrint(request.arena, "{{\"error\":\"{s}\"}}", .{message});
        try request.respond(body, .{
            .status = status,
            .extra_headers = &.{
                .{ .name = "Content-Type", .value = "application/json" },
            },
        });
    }

    fn handleSignal(sig: c_int) callconv(.C) void {
        _ = sig;
        std.log.info("Received shutdown signal", .{});
    }
};

fn loadConfig(allocator: mem.Allocator) !Config {
    const env_map = try std.process.getEnvMap(allocator);
    defer env_map.deinit();

    return Config{
        .cerebras_api_key = try allocator.dupe(u8, env_map.get("CEREBRAS_API_KEY") orelse return error.MissingApiKey),
        .dragonfly_url = try allocator.dupe(u8, env_map.get("DRAGONFLY_URL") orelse "127.0.0.1:6379"),
        .dragonfly_password = try allocator.dupe(u8, env_map.get("DRAGONFLY_PASSWORD") orelse ""),
        .modal_api_url = try allocator.dupe(u8, env_map.get("MODAL_API_URL") orelse return error.MissingModalUrl),
        .modal_api_key = try allocator.dupe(u8, env_map.get("MODAL_API_KEY") orelse ""),
        .kdb_host = try allocator.dupe(u8, env_map.get("KDB_HOST") orelse "127.0.0.1"),
        .kdb_port = if (env_map.get("KDB_PORT")) |port| try std.fmt.parseInt(u16, port, 10) else 5001,
        .listen_addr = try allocator.dupe(u8, env_map.get("LISTEN_ADDR") orelse "0.0.0.0"),
        .listen_port = if (env_map.get("LISTEN_PORT")) |port| try std.fmt.parseInt(u16, port, 10) else 8080,
        .num_threads = if (env_map.get("NUM_THREADS")) |nt| try std.fmt.parseInt(u32, nt, 10) else 128,
    };
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const config = try loadConfig(allocator);

    const server = try Server.init(allocator, config);
    defer server.deinit();

    const act = std.os.linux.Sigaction{
        .handler = .{ .handler = Server.handleSignal },
        .mask = std.os.linux.empty_sigset,
        .flags = 0,
    };
    try std.os.linux.sigaction(std.os.linux.SIG.TERM, &act, null);
    try std.os.linux.sigaction(std.os.linux.SIG.INT, &act, null);

    try server.start();

    std.log.info("Gateway shutting down gracefully", .{});
}
