const std = @import("std");
const http = std.http;
const mem = std.mem;
const json = std.json;
const Allocator = mem.Allocator;

pub const ModelTier = enum {
    speed,
    balanced,
    smart,

    pub fn modelName(self: ModelTier) []const u8 {
        return switch (self) {
            .speed => "qwen-235b",
            .balanced => "gpt-oss-120b",
            .smart => "glm-4.7-thinking",
        };
    }

    pub fn maxTokens(self: ModelTier) u32 {
        return switch (self) {
            .speed => 20000,
            .balanced => 32000,
            .smart => 65000,
        };
    }
};

pub const StreamChunk = struct {
    content: []const u8,
    done: bool,
};

pub const CerebrasClient = struct {
    allocator: Allocator,
    api_key: []const u8,
    http_client: http.Client,
    base_url: []const u8,

    pub fn init(allocator: Allocator, api_key: []const u8) !*CerebrasClient {
        const self = try allocator.create(CerebrasClient);
        self.allocator = allocator;
        self.api_key = try allocator.dupe(u8, api_key);
        self.http_client = http.Client{ .allocator = allocator };
        self.base_url = "";
        return self;
    }

    pub fn deinit(self: *CerebrasClient) void {
        self.http_client.deinit();
        self.allocator.free(self.api_key);
        self.allocator.destroy(self);
    }

    pub fn complete(self: *CerebrasClient, allocator: Allocator, tier: ModelTier, messages: []const json.Value, stream: bool) ![]u8 {
        var request_body = std.ArrayList(u8).init(allocator);
        defer request_body.deinit();

        var writer = request_body.writer();
        try writer.writeAll("{\"model\":\"");
        try writer.writeAll(tier.modelName());
        try writer.writeAll("\",\"messages\":[");

        for (messages, 0..) |msg, i| {
            if (i > 0) try writer.writeAll(",");
            try json.stringify(msg, .{}, writer);
        }

        try writer.writeAll("],\"max_tokens\":");
        try std.fmt.formatInt(tier.maxTokens(), 10, .lower, .{}, writer);
        try writer.writeAll(",\"temperature\":0.7,\"stream\":");
        try writer.writeAll(if (stream) "true" else "false");
        try writer.writeAll("}");

        var retries: u8 = 0;
        const max_retries = 3;

        while (retries < max_retries) {
            const result = self.makeRequest(allocator, request_body.items, stream) catch |err| {
                retries += 1;
                if (retries >= max_retries) return err;
                const backoff_ms = @as(u64, 1000) * (@as(u64, 1) << @intCast(retries - 1));
                std.time.sleep(backoff_ms * std.time.ns_per_ms);
                continue;
            };
            return result;
        }

        return error.MaxRetriesExceeded;
    }

    fn makeRequest(self: *CerebrasClient, allocator: Allocator, body: []const u8, stream: bool) ![]u8 {
        _ = stream;

        const uri = try std.Uri.parse(self.base_url);
        var headers = http.Headers{ .allocator = allocator };
        defer headers.deinit();

        var auth_header_buf: [512]u8 = undefined;
        const auth_header = try std.fmt.bufPrint(&auth_header_buf, "Bearer {s}", .{self.api_key});
        try headers.append("Authorization", auth_header);
        try headers.append("Content-Type", "application/json");
        try headers.append("Accept", "application/json");

        var request = try self.http_client.open(.POST, uri, headers, .{});
        defer request.deinit();

        request.transfer_encoding = .{ .content_length = body.len };

        try request.send(.{});
        try request.writeAll(body);
        try request.finish();
        try request.wait();

        if (request.response.status != .ok) {
            return error.ApiRequestFailed;
        }

        var response_body = std.ArrayList(u8).init(allocator);
        defer response_body.deinit();

        const reader = request.reader();
        try reader.readAllArrayList(&response_body, 10 * 1024 * 1024);

        return try allocator.dupe(u8, response_body.items);
    }

    pub fn streamComplete(self: *CerebrasClient, allocator: Allocator, tier: ModelTier, messages: []const json.Value, callback: *const fn (allocator: Allocator, chunk: StreamChunk) anyerror!void) !void {
        var request_body = std.ArrayList(u8).init(allocator);
        defer request_body.deinit();

        var writer = request_body.writer();
        try writer.writeAll("{\"model\":\"");
        try writer.writeAll(tier.modelName());
        try writer.writeAll("\",\"messages\":[");

        for (messages, 0..) |msg, i| {
            if (i > 0) try writer.writeAll(",");
            try json.stringify(msg, .{}, writer);
        }

        try writer.writeAll("],\"max_tokens\":");
        try std.fmt.formatInt(tier.maxTokens(), 10, .lower, .{}, writer);
        try writer.writeAll(",\"temperature\":0.7,\"stream\":true}");

        const uri = try std.Uri.parse(self.base_url);
        var headers = http.Headers{ .allocator = allocator };
        defer headers.deinit();

        var auth_header_buf: [512]u8 = undefined;
        const auth_header = try std.fmt.bufPrint(&auth_header_buf, "Bearer {s}", .{self.api_key});
        try headers.append("Authorization", auth_header);
        try headers.append("Content-Type", "application/json");
        try headers.append("Accept", "text/event-stream");

        var request = try self.http_client.open(.POST, uri, headers, .{});
        defer request.deinit();

        request.transfer_encoding = .{ .content_length = request_body.items.len };

        try request.send(.{});
        try request.writeAll(request_body.items);
        try request.finish();
        try request.wait();

        if (request.response.status != .ok) {
            return error.ApiRequestFailed;
        }

        const reader = request.reader();
        var line_buffer: [4096]u8 = undefined;
        var partial_buffer = std.ArrayList(u8).init(allocator);
        defer partial_buffer.deinit();

        while (true) {
            const line = reader.readUntilDelimiter(&line_buffer, '\n') catch |err| {
                if (err == error.EndOfStream) break;
                return err;
            };

            if (line.len == 0) continue;
            if (!mem.startsWith(u8, line, "data: ")) continue;

            const data = mem.trim(u8, line[6..], &std.ascii.whitespace);
            if (mem.eql(u8, data, "[DONE]")) {
                try callback(allocator, .{ .content = "", .done = true });
                break;
            }

            const parsed = json.parseFromSlice(json.Value, allocator, data, .{}) catch continue;
            defer parsed.deinit();

            if (parsed.value.object.get("choices")) |choices| {
                if (choices.array.items.len > 0) {
                    if (choices.array.items[0].object.get("delta")) |delta| {
                        if (delta.object.get("content")) |content| {
                            try callback(allocator, .{ .content = content.string, .done = false });
                        }
                    }
                }
            }
        }
    }

    pub fn extractContent(allocator: Allocator, response: []const u8) ![]u8 {
        const parsed = try json.parseFromSlice(json.Value, allocator, response, .{});
        defer parsed.deinit();

        if (parsed.value.object.get("choices")) |choices| {
            if (choices.array.items.len > 0) {
                if (choices.array.items[0].object.get("message")) |message| {
                    if (message.object.get("content")) |content| {
                        return try allocator.dupe(u8, content.string);
                    }
                }
            }
        }

        return error.NoContentInResponse;
    }
};
