const std = @import("std");
const mem = std.mem;
const crypto = std.crypto;
const Allocator = mem.Allocator;
const CerebrasClient = @import("cerebras_client.zig").CerebrasClient;
const ModelTier = @import("cerebras_client.zig").ModelTier;
const DragonflyClient = @import("dragonfly_client.zig").DragonflyClient;
const ModalClient = @import("modal_client.zig").ModalClient;
const KdbLogger = @import("kdb_logger.zig").KdbLogger;
const json = std.json;

pub const QueryResult = struct {
    response: []const u8,
    model: []const u8,
    tokens: u32,
    cache_hit: bool,
};

pub const Router = struct {
    allocator: Allocator,
    cerebras: *CerebrasClient,
    dragonfly: *DragonflyClient,
    modal: *ModalClient,
    kdb: *KdbLogger,
    stats_mutex: std.Thread.Mutex,
    total_queries: u64,
    cache_hits: u64,
    speed_queries: u64,
    balanced_queries: u64,
    smart_queries: u64,

    pub fn init(allocator: Allocator, cerebras: *CerebrasClient, dragonfly: *DragonflyClient, modal: *ModalClient, kdb: *KdbLogger) !*Router {
        const self = try allocator.create(Router);
        self.allocator = allocator;
        self.cerebras = cerebras;
        self.dragonfly = dragonfly;
        self.modal = modal;
        self.kdb = kdb;
        self.stats_mutex = std.Thread.Mutex{};
        self.total_queries = 0;
        self.cache_hits = 0;
        self.speed_queries = 0;
        self.balanced_queries = 0;
        self.smart_queries = 0;
        return self;
    }

    pub fn deinit(self: *Router) void {
        self.allocator.destroy(self);
    }

    pub fn handleQuery(self: *Router, allocator: Allocator, query: []const u8, deep_research: bool) !QueryResult {
        self.stats_mutex.lock();
        self.total_queries += 1;
        self.stats_mutex.unlock();

        const cache_key = try self.getCacheKey(allocator, query);
        defer allocator.free(cache_key);

        if (try self.dragonfly.get(allocator, cache_key)) |cached| {
            self.stats_mutex.lock();
            self.cache_hits += 1;
            self.stats_mutex.unlock();

            const parsed = try json.parseFromSlice(json.Value, allocator, cached, .{});
            defer parsed.deinit();

            const response = try allocator.dupe(u8, parsed.value.object.get("response").?.string);
            const model = try allocator.dupe(u8, parsed.value.object.get("model").?.string);
            const tokens = @as(u32, @intCast(parsed.value.object.get("tokens").?.integer));

            allocator.free(cached);

            return QueryResult{
                .response = response,
                .model = model,
                .tokens = tokens,
                .cache_hit = true,
            };
        }

        const complexity = self.analyzeComplexity(query, deep_research);
        const tier = self.selectModelTier(complexity, deep_research);

        self.stats_mutex.lock();
        switch (tier) {
            .speed => self.speed_queries += 1,
            .balanced => self.balanced_queries += 1,
            .smart => self.smart_queries += 1,
        }
        self.stats_mutex.unlock();

        const documents = try self.retrieveDocuments(allocator, query);
        defer allocator.free(documents);

        const context = try self.buildContext(allocator, query, documents);
        defer allocator.free(context);

        var messages = std.ArrayList(json.Value).init(allocator);
        defer messages.deinit();

        var system_obj = std.StringHashMap(json.Value).init(allocator);
        defer system_obj.deinit();
        try system_obj.put("role", .{ .string = "system" });
        try system_obj.put("content", .{ .string = "You are a helpful AI search assistant. Answer questions based on the provided context." });
        try messages.append(.{ .object = system_obj });

        var user_obj = std.StringHashMap(json.Value).init(allocator);
        defer user_obj.deinit();
        try user_obj.put("role", .{ .string = "user" });
        try user_obj.put("content", .{ .string = context });
        try messages.append(.{ .object = user_obj });

        const llm_response = try self.cerebras.complete(allocator, tier, messages.items, false);
        defer allocator.free(llm_response);

        const content = try CerebrasClient.extractContent(allocator, llm_response);

        const tokens = @as(u32, @intCast(content.len / 4));

        const ttl: u32 = if (complexity > 50) 21600 else 3600;
        try self.cacheResult(allocator, cache_key, content, tier.modelName(), tokens, ttl);

        const response = try allocator.dupe(u8, content);
        const model = try allocator.dupe(u8, tier.modelName());

        allocator.free(content);

        return QueryResult{
            .response = response,
            .model = model,
            .tokens = tokens,
            .cache_hit = false,
        };
    }

    fn analyzeComplexity(self: *Router, query: []const u8, deep_research: bool) u32 {
        _ = self;
        var score: u32 = 0;

        if (query.len > 200) score += 30;
        if (query.len > 400) score += 20;

        const keywords = [_][]const u8{ "compare", "vs", "versus", "implement", "code", "analyze", "explain deeply", "technical", "detailed", "comprehensive" };
        for (keywords) |keyword| {
            if (std.ascii.indexOfIgnoreCase(query, keyword)) |_| {
                score += 10;
            }
        }

        if (deep_research) score += 50;

        return @min(score, 100);
    }

    fn selectModelTier(self: *Router, complexity: u32, deep_research: bool) ModelTier {
        _ = self;
        if (deep_research or complexity >= 70) {
            return .smart;
        } else if (complexity >= 40) {
            return .balanced;
        } else {
            return .speed;
        }
    }

    fn getCacheKey(self: *Router, allocator: Allocator, query: []const u8) ![]u8 {
        _ = self;
        var hasher = crypto.hash.sha2.Sha256.init(.{});
        hasher.update(query);
        var hash: [32]u8 = undefined;
        hasher.final(&hash);

        var key = try allocator.alloc(u8, 13 + 64);
        @memcpy(key[0..13], "cache:query:");
        _ = try std.fmt.bufPrint(key[13..], "{s}", .{std.fmt.fmtSliceHexLower(&hash)});

        return key;
    }

    fn retrieveDocuments(self: *Router, allocator: Allocator, query: []const u8) ![]const u8 {
        const search_result = try self.modal.vectorSearch(allocator, query, 100, 128);
        return search_result;
    }

    fn buildContext(self: *Router, allocator: Allocator, query: []const u8, documents: []const u8) ![]u8 {
        _ = self;
        var context = std.ArrayList(u8).init(allocator);
