const std = @import("std");
const http = std.http;
const mem = std.mem;
const json = std.json;
const Allocator = mem.Allocator;

pub const ModalClient = struct {
    allocator: Allocator,
    api_url: []const u8,
    api_key: []const u8,
    http_client: http.Client,

    pub fn init(allocator: Allocator, api_url: []const u8, api_key: []const u8) !*ModalClient {
        const self = try allocator.create(ModalClient);
        self.allocator = allocator;
        self.api_url = try allocator.dupe(u8, api_url);
        self.api_key = try allocator.dupe(u8, api_key);
        self.http_client = http.Client{ .allocator = allocator };
        return self;
    }

    pub fn deinit(self: *ModalClient) void {
        self.http_client.deinit();
        self.allocator.free(self.api_url);
        self.allocator.free(self.api_key);
        self.allocator.destroy(self);
    }

    pub fn vectorSearch(self: *ModalClient, allocator: Allocator, query: []const u8, k: u32, nprobe: u32) ![]u8 {
        const embedding = try self.encodeQuery(allocator, query);
        defer allocator.free(embedding);

        var request_body = std.ArrayList(u8).init(allocator);
        defer request_body.deinit();

        var writer = request_body.writer();
        try writer.writeAll("{\"query_embedding\":[");

        const parsed = try json.parseFromSlice(json.Value, allocator, embedding, .{});
        defer parsed.deinit();

        const emb_array = parsed.value.array.items;
        for (emb_array, 0..) |val, i| {
            if (i > 0) try writer.writeAll(",");
            try std.fmt.formatFloat(val.float, .{}, writer);
        }

        try writer.writeAll("],\"k\":");
        try std.fmt.formatInt(k, 10, .lower, .{}, writer);
        try writer.writeAll(",\"nprobe\":");
        try std.fmt.formatInt(nprobe, 10, .lower, .{}, writer);
        try writer.writeAll("}");

        const url = try std.fmt.allocPrint(allocator, "{s}/search", .{self.api_url});
        defer allocator.free(url);

        var retries: u8 = 0;
        while (retries < 2) {
            const result = self.makeRequest(allocator, url, request_body.items) catch |err| {
                retries += 1;
                if (retries >= 2) return err;
                std.time.sleep(500 * std.time.ns_per_ms);
                continue;
            };
            return result;
        }

        return error.MaxRetriesExceeded;
    }

    fn encodeQuery(self: *ModalClient, allocator: Allocator, query: []const u8) ![]u8 {
        var request_body = std.ArrayList(u8).init(allocator);
        defer request_body.deinit();

        var writer = request_body.writer();
        try writer.writeAll("{\"texts\":[\"");
        try json.encodeJsonString(query, .{}, writer);
        try writer.writeAll("\"],\"max_length\":512}");

        const url = try std.fmt.allocPrint(allocator, "{s}/encode", .{self.api_url});
        defer allocator.free(url);

        const response = try self.makeRequest(allocator, url, request_body.items);
        defer allocator.free(response);

        const parsed = try json.parseFromSlice(json.Value, allocator, response, .{});
        defer parsed.deinit();

        const embeddings = parsed.value.object.get("embeddings").?.array.items;
        const first_embedding = embeddings[0].array.items;

        var result = std.ArrayList(u8).init(allocator);
        var result_writer = result.writer();
        try result_writer.writeAll("[");
        for (first_embedding, 0..) |val, i| {
            if (i > 0) try result_writer.writeAll(",");
            try std.fmt.formatFloat(val.float, .{}, result_writer);
        }
        try result_writer.writeAll("]");

        return try result.toOwnedSlice();
    }

    fn makeRequest(self: *ModalClient, allocator: Allocator, url: []const u8, body: []const u8) ![]u8 {
        const uri = try std.Uri.parse(url);
        var headers = http.Headers{ .allocator = allocator };
        defer headers.deinit();

        try headers.append("Content-Type", "application/json");
        if (self.api_key.len > 0) {
            var auth_header_buf: [512]u8 = undefined;
            const auth_header = try std.fmt.bufPrint(&auth_header_buf, "Bearer {s}", .{self.api_key});
            try headers.append("Authorization", auth_header);
        }

        var request = try self.http_client.open(.POST, uri, headers, .{});
        defer request.deinit();

        request.transfer_encoding = .{ .content_length = body.len };

        try request.send(.{});
        try request.writeAll(body);
        try request.finish();
        try request.wait();

        if (request.response.status != .ok) {
            return error.ApiRequestFailed;
        }

        var response_body = std.ArrayList(u8).init(allocator);
        defer response_body.deinit();

        const reader = request.reader();
        try reader.readAllArrayList(&response_body, 10 * 1024 * 1024);

        return try allocator.dupe(u8, response_body.items);
    }
};
