const std = @import("std");
const net = std.net;
const mem = std.mem;
const Allocator = mem.Allocator;

pub const KdbLogger = struct {
    allocator: Allocator,
    host: []const u8,
    port: u16,
    connection: ?net.Stream,
    connection_mutex: std.Thread.Mutex,
    buffer: std.ArrayList(Metric),
    buffer_mutex: std.Thread.Mutex,
    flush_thread: ?std.Thread,
    shutdown: std.atomic.Atomic(bool),

    const Metric = union(enum) {
        query: QueryMetric,
        crawler: CrawlerMetric,
        gpu: GpuMetric,
    };

    const QueryMetric = struct {
        time: i64,
        model: []const u8,
        latency: f64,
        tokens: u32,
        cache_hit: bool,
    };

    const CrawlerMetric = struct {
        time: i64,
        domain: []const u8,
        response_time: f64,
        status_code: u32,
    };

    const GpuMetric = struct {
        time: i64,
        gpu_id: u32,
        temperature: f64,
        memory_used: u64,
        utilization: f64,
    };

    pub fn init(allocator: Allocator, host: []const u8, port: u16) !*KdbLogger {
        const self = try allocator.create(KdbLogger);
        self.allocator = allocator;
        self.host = try allocator.dupe(u8, host);
        self.port = port;
        self.connection = null;
        self.connection_mutex = std.Thread.Mutex{};
        self.buffer = std.ArrayList(Metric).init(allocator);
        self.buffer_mutex = std.Thread.Mutex{};
        self.shutdown = std.atomic.Atomic(bool).init(false);
        self.flush_thread = null;
        return self;
    }

    pub fn deinit(self: *KdbLogger) void {
        self.shutdown.store(true, .Release);
        if (self.flush_thread) |thread| {
            thread.join();
        }
        self.flushBuffer();
        if (self.connection) |conn| {
            conn.close();
        }
        self.buffer.deinit();
        self.allocator.free(self.host);
        self.allocator.destroy(self);
    }

    pub fn connect(self: *KdbLogger) !void {
        const stream = try net.tcpConnectToHost(self.allocator, self.host, self.port);
        self.connection = stream;

        self.flush_thread = try std.Thread.spawn(.{}, flushLoop, .{self});
    }

    pub fn isConnected(self: *KdbLogger) bool {
        return self.connection != null;
    }

    fn flushLoop(self: *KdbLogger) void {
        while (!self.shutdown.load(.Acquire)) {
            std.time.sleep(100 * std.time.ns_per_ms);
            self.flushBuffer();
        }
    }

    fn flushBuffer(self: *KdbLogger) void {
        self.buffer_mutex.lock();
        defer self.buffer_mutex.unlock();

        if (self.buffer.items.len == 0) return;

        for (self.buffer.items) |metric| {
            self.sendMetric(metric) catch |err| {
                std.log.err("Failed to send metric: {}", .{err});
            };
        }

        self.buffer.clearRetainingCapacity();
    }

    pub fn logQuery(self: *KdbLogger, time: i64, model: []const u8, latency: f64, tokens: u32, cache_hit: bool) !void {
        self.buffer_mutex.lock();
        defer self.buffer_mutex.unlock();

        const model_copy = try self.allocator.dupe(u8, model);
        try self.buffer.append(.{
            .query = .{
                .time = time,
                .model = model_copy,
                .latency = latency,
                .tokens = tokens,
                .cache_hit = cache_hit,
            },
        });

        if (self.buffer.items.len >= 1000) {
            self.flushBuffer();
        }
    }

    pub fn logCrawler(self: *KdbLogger, time: i64, domain: []const u8, response_time: f64, status_code: u32) !void {
        self.buffer_mutex.lock();
        defer self.buffer_mutex.unlock();

        const domain_copy = try self.allocator.dupe(u8, domain);
        try self.buffer.append(.{
            .crawler = .{
                .time = time,
                .domain = domain_copy,
                .response_time = response_time,
                .status_code = status_code,
            },
        });

        if (self.buffer.items.len >= 1000) {
            self.flushBuffer();
        }
    }

    pub fn logGpu(self: *KdbLogger, time: i64, gpu_id: u32, temperature: f64, memory_used: u64, utilization: f64) !void {
        self.buffer_mutex.lock();
        defer self.buffer_mutex.unlock();

        try self.buffer.append(.{
            .gpu = .{
                .time = time,
                .gpu_id = gpu_id,
                .temperature = temperature,
                .memory_used = memory_used,
                .utilization = utilization,
            },
        });

        if (self.buffer.items.len >= 1000) {
            self.flushBuffer();
        }
    }

    fn sendMetric(self: *KdbLogger, metric: Metric) !void {
        self.connection_mutex.lock();
        defer self.connection_mutex.unlock();

        const conn = self.connection orelse return error.NotConnected;

        var buf: [1024]u8 = undefined;
        var fba = std.heap.FixedBufferAllocator.init(&buf);
        const allocator = fba.allocator();

        const message = switch (metric) {
            .query => |q| try std.fmt.allocPrint(allocator, "`.u.upd[`queries;({0d};`{s};{d};{d};{d}b)]\n", .{ q.time, q.model, q.latency, q.tokens, q.cache_hit }),
            .crawler => |c| try std.fmt.allocPrint(allocator, "`.u.upd[`crawler;({0d};`{s};{d};{d})]\n", .{ c.time, c.domain, c.response_time, c.status_code }),
            .gpu => |g| try std.fmt.allocPrint(allocator, "`.u.upd[`gpu;({0d};{d};{d};{d};{d})]\n", .{ g.time, g.gpu_id, g.temperature, g.memory_used, g.utilization }),
        };

        _ = try conn.write(message);
    }
