const std = @import("std");
const mem = std.mem;
const json = std.json;

pub const StreamParser = struct {
    buffer: std.ArrayList(u8),
    allocator: mem.Allocator,

    pub fn init(allocator: mem.Allocator) StreamParser {
        return .{
            .buffer = std.ArrayList(u8).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *StreamParser) void {
        self.buffer.deinit();
    }

    pub fn parseChunk(self: *StreamParser, chunk: []const u8) !?[]const u8 {
        try self.buffer.appendSlice(chunk);

        const data_prefix = "data: ";
        var start: usize = 0;

        while (mem.indexOf(u8, self.buffer.items[start..], data_prefix)) |offset| {
            const data_start = start + offset + data_prefix.len;
            const line_end = mem.indexOf(u8, self.buffer.items[data_start..], "\n") orelse {
                return null;
            };

            const data = self.buffer.items[data_start .. data_start + line_end];

            if (mem.eql(u8, mem.trim(u8, data, &std.ascii.whitespace), "[DONE]")) {
                return null;
            }

            if (!std.unicode.utf8ValidateSlice(data)) {
                start = data_start + line_end + 1;
                continue;
            }

            const parsed = json.parseFromSlice(json.Value, self.allocator, data, .{}) catch {
                start = data_start + line_end + 1;
                continue;
            };
            defer parsed.deinit();

            if (parsed.value.object.get("choices")) |choices| {
                if (choices.array.items.len > 0) {
                    if (choices.array.items[0].object.get("delta")) |delta| {
                        if (delta.object.get("content")) |content| {
                            const result = try self.allocator.dupe(u8, content.string);

                            self.buffer.clearRetainingCapacity();
                            return result;
                        }
                    }
                }
            }

            start = data_start + line_end + 1;
        }

        return null;
    }

    pub fn reset(self: *StreamParser) void {
        self.buffer.clearRetainingCapacity();
    }
};
